export async function payAndDeploy(
  prev: any,
  formData: FormData,
): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
  const user = await requireUser();
  // Spend path: never move a customer's money while an admin is impersonating them.
  // Caught (not left to throw uncaught) so an impersonating admin sees this exact
  // message inline — the bare throw used to crash the whole page with a generic
  // "Something went wrong" screen instead, a real bug hit every time an admin
  // testing the wizard while impersonating tried to pay.
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
  }
  // Same verification gate every purchase path applies. This is the CARD path, so it is the
  // one where an unreachable address is most expensive: without it we would take
  // a real payment for a machine whose credentials have nowhere to go.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };
  // Per-user server cap — the same one `orderGameServer` enforces for game tiers.
  const limitErr = await serverLimitError(user.id);
  if (limitErr) return { error: limitErr };
  const intent = intentFromFormData(formData);
  // Tag the order if the customer arrived via a partner deep link (?ref=kodely on
  // /dashboard/deploy, captured into a cookie by PartnerSourceCapture). Undefined
  // for a direct order, so it drops out of the Stripe-metadata JSON round-trip
  // like extraDiskGB/backupTier above.
  intent.partnerSource = partnerSourceFromCookie(await cookies());

  let quote;
  try {
    quote = await orderQuote(intent);
  } catch (e) {
    if (e instanceof OrderError) return { error: e.message };
    throw e;
  }

  // Managed first-month-free eligibility. If this account/IP has ALREADY redeemed
  // the promo (or it's switched off), re-quote at FULL price so the wallet split,
  // the card leg and the stamped total are all full — the free month is a
  // once-per-person offer. The wallet path is self-correcting regardless (its
  // atomic claim inside placeOrder charges full on a lost claim), but the CARD
  // leg settles up front, so it MUST be priced full here or a repeat customer
  // gets a second discounted checkout. This mirrors the coupon guard below.
  // `|| null` matters: hashIp returns "" when the IP is unavailable, and an empty
  // string is a REAL value to the (promoId, ipHash) unique — it would collide
  // across every IP-less redemption and wrongly block them. NULLs are distinct.
  const promoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
  if (quote.promoCreditCents > 0 && !(await firstMonthFreeEligible(user.id, promoIpHash))) {
    quote = await orderQuote(intent, { suppressPromo: true });
  }
  const promoCampaign = promoCampaignFromCookie(await cookies());

  const isAdmin = user.role === "ADMIN";
  const freePath = !!intent.free && isAdmin;

  // Wallet-aware split. The customer's Review screen computes the exact same split
  // (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
  // `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
