  // VAT/GST for this customer (Finding 1), resolved from their billing country. The
  // rate is constant for the request; the tax cents track whatever net the quote
  // settles on after any promo/coupon re-quote below. The wallet split and the card
  // leg are computed from the TAX-INCLUSIVE total so the card is charged the same
  // total the customer is shown, and the stamped `OrderPrice` carries the tax so the
  // confirm route settles it without re-deriving. A free admin grant is never taxed.
  const taxCtx = freePath ? { ratePercent: 0, country: "", reverseCharged: false } : await taxContextForUser(user);
